example_item.example_item_data:
filename = [tempname(), '.mat'];
m = matfile(filename)
m.savedVar(81:100, 81:100) = magic(20);
[nrows, ncols] = size(m, 'savedVar')
loadVar = m.savedVar(nrows - 19:nrows, 86:95)

filename = [tempname(), '.mat'];
stocks = rand(1000, 4);
savemat(filename, 'stocks', '-v7.3');
m = matfile(filename);
[nrows, ncols] = size(m, 'stocks');
avgs = zeros(1, ncols);
for k = 1:ncols
  avgs(k) = mean(m.stocks(:, k));
end
avgs

filename = [tempname(), '.mat'];
x = magic(4);
savemat(filename, 'x', '-v7.3');
m = matfile(filename);
m.Properties.Writable = true;
m.x(2, :) = [0 0 0 0];
m.y = 'new variable';
whos(m)
